(function(){
  var root=document.getElementById('zb-lift');
  var SRC={platform:'data:image/png;base64,',base:'data:image/png;base64,',text:'data:image/png;base64,',warn:'data:image/png;base64,'};
  var MAXLIFT=parseFloat(root.getAttribute('data-lift'))||800;
  var MODE=root.getAttribute('data-mode')||'auto'; // 'auto' = Loop, 'manual' = nur setProgress()
  var T=59, BAR=944, LP=BAR-58, CX=620, YBOT=877, N=4, Y0=MAXLIFT, VH=Y0+1188;
  var NS='http://www.w3.org/2000/svg';
  root.innerHTML='<svg xmlns="'+NS+'" viewBox="0 0 1239 '+VH+'" width="100%" style="display:block;height:auto" role="img" aria-label="Scherenarbeitsbühne fährt aus">'+
  '<defs>'+
  '<linearGradient id="zbBar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8d8d90"/><stop offset=".05" stop-color="#5c5c60"/><stop offset=".5" stop-color="#4d4d51"/><stop offset="1" stop-color="#38383b"/></linearGradient>'+
  '<radialGradient id="zbBolt" cx=".4" cy=".35" r=".7"><stop offset="0" stop-color="#6a6a6e"/><stop offset=".6" stop-color="#26262a"/><stop offset="1" stop-color="#0d0d0f"/></radialGradient>'+
  '<radialGradient id="zbShadow"><stop offset="0" stop-color="#000" stop-opacity=".38"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>'+
  '</defs>'+
  '<ellipse cx="620" cy="'+(Y0+1172)+'" rx="560" ry="26" fill="url(#zbShadow)"/>'+
  '<g id="zbArms"></g>'+
  '<image id="zbBase" href="'+SRC.base+'" x="0" y="'+(Y0+850)+'" width="1239" height="338"/>'+
  '<image id="zbPlat" href="'+SRC.platform+'" x="0" y="'+Y0+'" width="1239" height="676"/>'+
  '</svg>';
  var arms=root.querySelector('#zbArms'), plat=root.querySelector('#zbPlat');
  function bolt(x,y,r){return '<circle cx="'+x+'" cy="'+y+'" r="'+(r+3)+'" fill="#1a1a1c"/><circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="url(#zbBolt)" stroke="#000" stroke-opacity=".5"/>';}
  function arm(yc,ang,front,stage){
    var s='<g transform="translate('+CX+' '+yc.toFixed(2)+') rotate('+ang.toFixed(3)+')">'+
      '<rect x="'+(-BAR/2)+'" y="-29" width="'+BAR+'" height="58" rx="9" fill="url(#zbBar)" stroke="#111" stroke-width="1.5"/>';
    if(front&&stage===1) s+='<image href="'+SRC.text+'" x="'+(279-CX)+'" y="'+(767-788.5)+'" width="706" height="47"/>';
    if(front&&stage===2) s+='<image href="'+SRC.warn+'" x="'+(225-CX)+'" y="'+(706-729.5)+'" width="793" height="47"/>';
    s+=bolt(-LP/2,0,14)+bolt(LP/2,0,14)+bolt(0,0,14)+'</g>';
    return s;
  }
  function render(p){
    p=Math.max(0,Math.min(1,p));
    var lift=p*MAXLIFT, sin=lift/(N*LP), th=Math.asin(Math.min(sin,.99))*180/Math.PI;
    var d=LP*sin+T, html='';
    for(var k=0;k<N;k++){
      var yc=Y0+YBOT-(k+.5)*d;
      html+=arm(yc,th,false,k)+arm(yc,-th,true,k);   // A (vorn, mit Aufklebern) steigt nach rechts
    }
    arms.innerHTML=html;
    plat.setAttribute('y',(Y0-lift).toFixed(2));
  }
  function ease(x){return x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;}
  // Zeitplan (Sekunden): hoch, halten, runter, halten
  var UP=3.4,HOLD1=1.4,DOWN=3.0,HOLD2=1.2,TOT=UP+HOLD1+DOWN+HOLD2;
  function at(t){t=t%TOT;
    if(t<UP) return ease(t/UP); t-=UP;
    if(t<HOLD1) return 1; t-=HOLD1;
    if(t<DOWN) return 1-ease(t/DOWN); return 0;}
  window.ScissorLift={setProgress:render,maxLift:MAXLIFT};
  render(0);
  var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(MODE==='auto'&&!reduce){
    var visible=true,t0=null;
    if('IntersectionObserver' in window) new IntersectionObserver(function(e){visible=e[0].isIntersecting;}).observe(root);
    (function loop(ts){
      if(t0===null) t0=ts;
      if(visible) render(at((ts-t0)/1000));
      requestAnimationFrame(loop);
    })(performance.now());
  }
})();
